"""Comparison-standard detector (layers.15.mlp.down_proj, component 839).

The component goes strongly negative on the word that introduces the standard of a
comparison, the word just before the thing being compared against:
  "Females are generally larger [than] males"      -> about -12 (up to -37 in the data)
  "the number of lives ... compared [to] other"    -> about -12 (compared to: -14 on average)
  "The hinges differ [from] those"                  -> about -10
  "is not the same [as] ..."                       -> about -4
Everything else is near zero. The strength depends on the words around it: "than" after
"more" or "less" is weaker, and "rather than" / "other than" are not comparisons at all.
Positions are scored from the current token and the one before it, within one document.
"""

READS = ()

# Comparison words that fire on their own, and their typical strength.
COMPARE_WORDS = {
    "compared": -8.0,
    "unlike": -7.0,
    "versus": -7.5,
    "vs": -3.0,
    "whereas": -4.5,
    "comparison": -3.5,
    "比": -11.0,
    "чем": -4.5,
    "较": -5.0,
    "較": -5.0,
    "超过": -5.0,
}

# Words that follow a comparison word, and the strength of the marker that follows them.
AFTER_COMPARE = {"compared", "comparison", "contrast", "relative"}
AFTER_SIMILAR = {"similar", "opposed", "equivalent", "parallel", "equals"}
AFTER_SAME = {"same", "much", "good", "just"}
AFTER_MULTIPLE = {"twice", "times", "than", "half"}


def _word(token: str) -> str:
    return token.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""

    if word == "than":
        if prev in ("rather", "other"):
            return carry, -1.0
        if prev in ("more", "less"):
            return carry, -4.0
        return carry, -12.0
    if word in COMPARE_WORDS:
        return carry, COMPARE_WORDS[word]
    if word == "to" and prev in AFTER_COMPARE:
        return carry, -12.0
    if word == "to" and prev in AFTER_SIMILAR:
        return carry, -3.0
    if word == "with" and prev in ("compared", "comparison"):
        return carry, -12.0
    if word == "from" and prev == "different":
        return carry, -9.5
    if word == "as" and prev in AFTER_SAME:
        return carry, -4.0
    if word == "the" and prev in AFTER_MULTIPLE:
        return carry, -5.0
    if word == "that" and prev == "than":
        return carry, -7.0
    if word == "of" and prev in ("ahead", "that"):
        return carry, -5.5
    return carry, 0.0

"""Layer 15, MLP down_proj, component 841: a weak, diffuse feature.

The component's activation is the MLP hidden unit 841 of layer 15 (times a fixed scale).
Read from the words, that unit leans positive on words of repetition, continuation and
reuse ("again", "same", "also", "still", "now", "continue", "used", "applied", "replaced")
and on auxiliaries ("will", "can", "is", "was", "be"), on the word right after an
auxiliary or repetition word ("will be", "can be", "was used", "again the"), and on "to".
It leans slightly negative on digits, code symbols and markup tokens.

This program adds those weights and a small negative baseline. It is a readable
approximation: it explains under 1% of the activation's variance (eval: about 0.4%).
Most of the activation is a broad, context-dependent spread with no word-level description;
a per-bigram lookup table reaches several percent on held-out text but has no concept
behind it, so it is not used here.
"""

READS = ()

REPEAT = {
    "again", "same", "also", "still", "now", "then", "too", "continue", "continued",
    "continues", "similar", "equally", "remain", "remains", "remained", "once", "further",
    "already", "yet",
}
REUSE = {
    "use", "used", "uses", "using", "apply", "applied", "applicable", "replace", "replaced",
    "converted", "convert", "pass", "passed", "passes", "work", "works", "follow", "follows",
    "extended", "carried", "reused", "reuse",
}
AUX = {
    "be", "is", "was", "were", "are", "been", "being", "am", "will", "would", "can", "may",
    "must", "should", "could", "might",
}
CODE = set(":(){};=+<>&|$[]*-/\\")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    value = -0.027
    if cur in REPEAT:
        value += 0.35
    if prev in REPEAT:
        value += 0.19
    if cur in REUSE:
        value += 0.17
    if prev in REUSE:
        value += 0.08
    if cur in AUX:
        value += 0.12
    if prev in AUX and cur.isalpha():
        value += 0.08
    if cur == "to":
        value += 0.085
    if cur.isdigit() or cur in CODE:
        value += 0.01
    if "<" in cur or cur.startswith('":') or cur.endswith('"}'):
        value -= 0.008
    return carry, value

"""Component layers.15.mlp.down_proj:842 -- a "vague quantity" detector.

When this component is strongly negative, the model is about to name a vague amount
or collection: "offers a [wide] variety of", "a [large] number of", "a range of",
"a few", "a lot of". Its output direction promotes words like variety, assortment,
plethora and numerous, so the negative spikes push the model toward those words.

When it is positive, the word is an "of" that follows a collection noun ("list of",
"sum of", "series of", "array of", "family of"): the mirror image of the negative side,
where the phrase is already named and the model is about to list its members.

The program predicts from the current word and the word before it:
  - an article ("a", "an") after a verb of offering or containing ("offers a",
    "features a", "contains a", "includes a", "are a") or after "quite" or "only"
    ("quite a few", "only a few") gets a strong negative value;
  - an article after a preposition ("with a", "by a", "through a") gets a weak negative
    value; other articles get a very small one;
  - an extent adjective after an article ("a wide", "a vast", "a broad") gets the
    largest negative value; elsewhere a smaller one;
  - a quantity noun ("variety", "range", "number", "lot", ...) gets a small negative value;
  - "of" after a collection noun gets a positive value;
  - vague determiners and small counts ("many", "several", "multiple", "all", "three") get
    a small positive value.
Every other word predicts 0.

Values are rough group means on training text. The program explains only a few percent
of the variance: most of the variance is spread over ordinary tokens, and the spikes depend
on context that a word-level rule cannot see.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

ARTICLES = {"a", "an"}
OFFERING_VERBS = {
    "offers", "offer", "offering", "features", "feature", "contains", "contain",
    "includes", "include", "including", "provides", "provide", "providing",
    "requires", "require", "generate", "generates", "covers", "cover", "boasts",
    "encompasses", "encompass", "presents", "present", "are", "quite", "only",
}
PREPOSITIONS = {"with", "by", "through", "for", "of", "from", "amid", "among", "over", "across"}
EXTENT_ADJECTIVES = {
    "wide", "vast", "broad", "large", "great", "huge", "whole", "entire", "full",
    "diverse", "extensive", "comprehensive", "impressive", "massive", "enormous",
    "considerable", "substantial", "tremendous", "immense", "numerous", "various",
}
QUANTITY_NOUNS = {
    "variety", "range", "number", "lot", "plethora", "multitude", "assortment",
    "array", "wealth", "majority", "bulk", "few", "series", "collection", "combination",
    "amount", "raft", "fleet", "profusion", "handful", "couple", "dozen",
}
COLLECTION_NOUNS = {
    "list", "lists", "sum", "collection", "series", "array", "set", "sequence", "product",
    "network", "union", "family", "team", "association", "federation", "plurality",
    "thousands", "millions", "grid", "vector", "dictionary", "hierarchy", "tree", "chain",
    "class", "genus", "number", "numbers", "variety", "range", "group", "mixture",
}
VAGUE_DETERMINERS = {
    "many", "several", "multiple", "all", "these", "among", "some",
    "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
}


def word(token: str) -> str:
    return token.strip().lower()


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    cur = word(prefix.token_strings[-1])
    same_doc = t > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = word(prefix.token_strings[-2]) if same_doc else ""

    if cur in ARTICLES:
        if prev in OFFERING_VERBS:
            return carry, -4.0
        return carry, -1.2 if prev in PREPOSITIONS else -0.5
    if cur in EXTENT_ADJECTIVES:
        return carry, -6.0 if prev in ARTICLES else -0.9
    if cur in QUANTITY_NOUNS:
        return carry, -0.7
    if cur == "of" and prev in COLLECTION_NOUNS:
        return carry, 3.5
    if cur in VAGUE_DETERMINERS:
        return carry, 0.5
    return carry, 0.0

"""Layers.15 MLP down_proj component 846: a weak detector of code structure.

It is quiet on most text (about 0 with small noise) and fires on the few
positions where source code starts a new declaration or block:
  * a declaration keyword that opens a line (import, from, def, func, fn,
    #include, public, class, const, using, package, ...): strong;
  * the same keywords elsewhere in code: mild;
  * indentation (tabs or spaces) that opens a line, or follows '{': mild.
Everything else predicts 0. The program explains only a few percent of the
variance: most of this component's activation is diffuse and not tied to
any token or local context we could name.
"""

DECLARATION_WORDS = {
    "import", "from", "def", "class", "func", "fn", "function", "const",
    "let", "var", "public", "private", "static", "void", "int", "using",
    "package", "include", "#include", "main", "return", "struct", "impl",
    "namespace", "export", "async",
}

READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix.token_strings) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        before = prefix.token_strings[-2]
    else:
        before = "\n"  # a new document starts a line
    word = tok.strip()
    line_start = before.endswith("\n") or before.endswith("\\n")
    if word in DECLARATION_WORDS:
        value = 2.5 if line_start else 0.4
    elif tok.strip() == "" and tok != "" and (line_start or before.endswith("{")):
        value = 0.4
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP unit 851, read as a word-level "eager anticipation" detector.

What the component is: its input direction is almost entirely one hidden unit of the
layer-15 MLP (index 851), so its activation is that unit's value. Its output direction,
read through the unembedding, promotes words of anticipation and dread: "dreaded",
"feared", "awaited", "welcomed", "relieved", "reluctantly", "迎来" (ushers in), "的到来"
(the arrival of). It is strongest in text that is looking forward to something: "looking
forward to", "eager to", "excited to", "can't wait", "time of year".

What this program does: it scores each word by a few word lists.
  - eager/excited words (excited, eager, anticipation, glad, ...) push the value up most;
  - hope, fear and welcome words (hope, wish, afraid, forward, wait, ...) push it up a little;
  - grateful and happy words push it up slightly;
  - first-person habit and feeling words ("always", "usually", "I'm", "'d", "feel") push it down;
  - a function word right after an eager or hope word ("to", "for", "about") counts as a follow-on.
Everything else is 0.

What it gets: it explains about 0.7% of the activation's variance on eval (Pearson r about
0.09). The component is diffuse: its variance is spread over many contexts, and no list of
words or simple window of words recovers most of it. A lookup table of token pairs fits
held-out text somewhat better (about 2.6% of variance in my test), but it is a table of
token ids with no concept behind it, so this program keeps the word lists instead.
In the model it changes next-token predictions by essentially the same amount as switching
the unit off (kl_fraction about 0.99).
"""

READS = ()

EAGER = {
    "excited", "excitement", "eager", "eagerly", "anticipation", "anticipate",
    "glad", "delighted", "期待",
}
HOPE_FEAR = {
    "hope", "hopes", "hoping", "wish", "wished", "afraid", "fear", "feared", "dreaded",
    "dread", "nervous", "worried", "怕", "forward", "welcome", "welcomed", "wait",
    "waiting", "await",
}
GRATEFUL = {
    "grateful", "gratitude", "thankful", "joy", "happy", "love", "loves", "ready",
    "looking", "appreciate",
}
HABIT = {
    "always", "usually", "often", "sometimes", "normally", "feel", "feels", "felt",
    "feeling", "'m", "'d", "'ll", "'ve",
}
CUE_NEXT = {"to", "for", "about", "of", "that"}


def word(text):
    """A token's text as a lowercase word, with its leading space and curly quotes removed."""
    return text.strip().lower().replace("’", "'")


def step(carry, prefix, upstream):
    """This component's activation at the newest token of the prefix."""
    w = word(prefix.token_strings[-1])
    same_doc = len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = word(prefix.token_strings[-2]) if same_doc else ""
    if w in EAGER:
        value = 3.5
    elif w in HOPE_FEAR:
        value = 0.6
    elif w in GRATEFUL:
        value = 0.6
    elif w in HABIT:
        value = -0.6
    elif w in CUE_NEXT and (prev in EAGER or prev in HOPE_FEAR):
        value = 1.2
    else:
        value = 0.0
    return carry, value

"""Predict the component's activation from position within its document.

Component p-82af68dd@100000/layers.15.mlp.down_proj:855 (layer 15 MLP down-projection).
Its activation is mostly token-level noise (mean 0.06, sd 0.27) that no word category,
token identity or document genre explains. The one regular pattern is where a token sits
in its document: the first token is about zero, the second and third are negative, and
from about the tenth token on the activation settles near its mean of about 0.06.

The program counts each token's position within its document (restarting at each new
document label) and returns the level for that position.
"""

READS = ()


def level(n):
    if n == 0:
        return 0.0
    if n < 3:
        return -0.08
    if n < 10:
        return 0.01
    if n < 30:
        return 0.04
    return 0.06


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n = 0
    else:
        n = carry[1] + 1
    return (doc, n), level(n)

"""Sentence and clause openers in English prose (layers.15.mlp.down_proj:857).

This component is mostly a negative signal that switches on at the first word of a new
sentence or clause. Its value, in the component's own units, is:

- about -4 on a determiner, expletive or pronoun that opens a sentence after a sentence end
  (. ! ?): "The", "In", "There", "It", "This", "I", "We", "Let", "For", "On", "Now";
- about -2 on any other capitalised word opening a sentence ("So", "And", "You", "However",
  "According", a proper noun, ...);
- about -1 on a weaker opener after a sentence end ("He", "She", "They", "If", "When", "But",
  "To", ...), and on the blank token (" " or newline) that starts a sentence after a period;
- about -1.5 on a clause subject right after a comma: "it", "there", "let", "we", "you",
  "that", "and", "but", "the";
- about -1 on the digit "1" when a bare space token comes before it (as in " 1");
- 0 otherwise (mid-sentence words, digits in numbers, list markers after a period, code).

Only the previous token and the current one are read, and the count restarts at every
document. The rule explains roughly 6% of the variance: the sign and the rough size of the
sentence-start negativity are right, but the component's large values depend on context
(prose versus lists or code) that no word list captures. A full lookup of word values
would add a few points more, at the cost of a large table.
"""

READS = ()

SENTENCE_END = {".", "!", "?"}
STRONG_OPENERS = {"the", "there", "in", "let", "for", "on", "it", "this", "i", "we", "now",
                  "according", "a"}
WEAK_OPENERS = {"he", "she", "they", "if", "when", "with", "by", "no", "since", "after",
                "all", "to", "these", "then", "but", "or", "so"}
CLAUSE_SUBJECTS = {"it", "there", "let", "we", "i", "you", "that", "the", "and", "but"}


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0  # first token of a document: nothing before it
    raw_prev = prefix.token_strings[-2]
    prev = raw_prev.strip()
    raw_cur = prefix.token_strings[-1]
    cur = raw_cur.strip()
    word = cur.isalpha()
    if prev in SENTENCE_END:
        if word and cur[:1].isupper():
            if cur.lower() in STRONG_OPENERS:
                return carry, -4.0
            if cur.lower() in WEAK_OPENERS:
                return carry, -1.0
            return carry, -2.0
        if cur == "":
            return carry, -1.0  # a blank token (space or newline) starting the sentence
    if prev == "," and word and cur.lower() in CLAUSE_SUBJECTS:
        return carry, -1.5
    if raw_prev == " " and cur == "1":
        return carry, -1.0
    return carry, 0.0

"""Word-class guess for a weak, context-driven component.

The component (layer 15 MLP down_proj, direction 865) is nearly silent in the model: its
activation is small (typical size 0.35), mostly context-dependent, and token identity explains
almost none of it. The only consistent token-level signal we found is the sign of the class
means below, so the program predicts a per-class mean of the current token.
"""

READS = ()

POSSESSIVE = {" my", " your", " his", " her", " its", " our", " their"}
ARTICLE = {" the", " a", " an"}
BASE_VERB = {" make", " take", " find", " learn", " get", " do", " have", " use", " go", " see", " know", " think"}
NEWLINE = {"\n", "\n\n", ".\n", ".\n\n"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in POSSESSIVE:
        value = 0.19
    elif tok in ARTICLE:
        value = -0.09
    elif tok in BASE_VERB:
        value = -0.07
    elif tok in NEWLINE:
        value = -0.07
    else:
        value = -0.03
    return carry, value

"""Naming-relation component (layer 15 MLP down_proj, unit 866).

What it does: it is a weak, mostly unexplained feature of the MLP hidden state.
Its large positive values come on the preposition or linking word that follows a
naming or origin verb ("named [after]", "stands [for]", "inspired [by]",
"comes [from]", "known [by]"). Its large negative values come on the word that
introduces an equivalence or comparison ("known [as]", "is [like]", "( [like]").

This program writes a small value on those word pairs and a constant baseline
elsewhere. The positive and negative values are the class means measured on
training text, not fitted per token.
"""

READS = ()

BASE = -0.03
NAMING = {"named", "inspired", "stands", "comes", "known", "called", "its", "name"}
PREPS = {"after", "for", "by", "from", "on"}
EQUIV_AS = {"known", "termed"}
EQUIV_LIKE = {"is", "("}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    t = prefix.position
    if t < 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, BASE
    prev = _word(prefix.token_strings[-2])
    cur = _word(prefix.token_strings[-1])
    if prev in NAMING and cur in PREPS:
        return carry, 0.40
    if prev in EQUIV_AS and cur == "as":
        return carry, -0.70
    if prev in EQUIV_LIKE and cur == "like":
        return carry, -0.80
    return carry, BASE

"""Predicts layers.15.mlp.down_proj component 870, a verb-clause feature.

In plain terms: this component is negative on the verb of a clause, most of all
on a main verb that comes straight after a subject pronoun or an auxiliary
("he says", "they have made"), with a smaller negative on verbs of speaking
and thinking. Auxiliaries themselves are mildly negative, "to" and possessive "'s" are mildly
negative too, and subject pronouns are mildly positive. Everything else is about zero.

Only the current word and the word before it are read, so each prediction is
causal. The sign and rough sizes come from fitting the component's activations
on training text; they are not an exact model of the component.
"""

from functools import lru_cache

import wordnet

READS = ()

PRONOUNS = {"i", "we", "you", "he", "she", "it", "they", "me", "us", "him", "her", "them"}
AUXILIARIES = {
    "has", "have", "had", "will", "would", "can", "could", "may", "might",
    "must", "shall", "should", "did", "does", "do", "cannot",
}
COPULAS = {"is", "was", "are", "were", "be", "been", "being", "am"}

AUX_VALUE = -1.0  # has, have, will, can ...
VERB_AFTER_SUBJECT = -1.4  # a main verb right after a pronoun or auxiliary
SPEECH_OR_THOUGHT = -0.4  # verbs of saying, telling, thinking, etc., elsewhere
OTHER_VERB = -0.1
PRONOUN_VALUE = 0.5
TO_OR_POSSESSIVE = -0.5  # "to" (infinitive marker) and "'s" / "’s"


@lru_cache(maxsize=None)
def is_main_verb(word):
    """A content verb: WordNet lists it as a verb, and it is not an auxiliary or copula."""
    if not word.isalpha() or word in AUXILIARIES or word in COPULAS:
        return False
    return "verb" in wordnet.parts_of_speech(word)


@lru_cache(maxsize=None)
def is_speech_or_thought(word):
    cats = wordnet.categories(word, "verb")
    return "verb.communication" in cats or "verb.cognition" in cats


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in AUXILIARIES:
        return carry, AUX_VALUE
    if word in PRONOUNS:
        return carry, PRONOUN_VALUE
    if word in ("to", "'s", "’s"):
        return carry, TO_OR_POSSESSIVE
    if is_main_verb(word):
        if before in PRONOUNS or before in AUXILIARIES:
            return carry, VERB_AFTER_SUBJECT
        if is_speech_or_thought(word):
            return carry, SPEECH_OR_THOUGHT
        return carry, OTHER_VERB
    return carry, 0.0
